<template>
  <article class="invoice-paper" dir="rtl">
    <header class="invoice-header" data-pdf-block>
      <div class="invoice-brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32" width="28" height="28" xmlns="http://www.w3.org/2000/svg"><path d="M7 13v6c0 5 18 5 18 0v-6" fill="none" stroke="#ffffff" stroke-width="2.5" stroke-linecap="round"/><circle cx="16" cy="9" r="1.8" fill="#ffffff"/></svg></span><div><strong>{{ brand.invoiceName }}</strong><p>{{ brand.invoiceSubtitle }}</p></div></div>
      <div class="invoice-heading"><span class="invoice-eyebrow">{{ document.kind === 'purchase' ? 'خرید کالا' : 'فروش کالا' }}</span><h1>{{ title }}</h1><span class="invoice-status">{{ statusText }}</span></div>
    </header>
    <section class="invoice-details" data-pdf-block>
      <div><span>{{ document.kind === 'purchase' ? 'تأمین‌کننده' : 'خریدار' }}</span><strong>{{ document.party_name || '—' }}</strong><p v-if="document.warehouse_name">انبار: {{ document.warehouse_name }}</p></div>
      <dl><div><dt>شماره سند</dt><dd dir="ltr">{{ document.number }}</dd></div><div><dt>تاریخ</dt><dd>{{ date(document.date) }}</dd></div><div><dt>واحد پول</dt><dd>تومان</dd></div></dl>
    </section>
    <p v-if="['draft', 'unissued', 'cancelled'].includes(document.billing_status)" class="invoice-notice" data-pdf-block>{{ notice }}</p>
    <table class="invoice-items"><thead><tr><th>شرح کالا</th><th>تعداد</th><th>بهای واحد</th><th>تخفیف</th><th>مبلغ</th></tr></thead><tbody>
      <tr v-for="(item, index) in document.items" :key="item.id || index" data-pdf-block><td><span class="item-index">{{ number(index + 1) }}</span><strong>{{ item.product_name }}</strong><small dir="ltr">{{ item.product_code }}</small></td><td data-label="تعداد">{{ number(item.quantity) }} <small>{{ item.unit }}</small></td><td data-label="بهای واحد">{{ money(item.unit_price) }}</td><td data-label="تخفیف">{{ money(item.discount) }}</td><td data-label="مبلغ" class="line-total">{{ money(item.line_total) }}</td></tr>
    </tbody></table>
    <section class="invoice-bottom" data-pdf-block>
      <div class="invoice-notes"><span class="invoice-eyebrow">یادداشت سند</span><p>{{ document.notes || 'یادداشتی برای این سند ثبت نشده است.' }}</p><p class="subtle">این سند بر اساس اطلاعات ثبت‌شده در سامانه تهیه شده است.</p></div>
      <dl class="invoice-totals"><div><dt>جمع اقلام</dt><dd>{{ money(document.subtotal) }}</dd></div><div><dt>تخفیف سند</dt><dd>{{ money(document.discount_amount) }}</dd></div><div><dt>مالیات</dt><dd>{{ money(document.tax_amount) }}</dd></div><div class="grand-total"><dt>مبلغ نهایی <small>تومان</small></dt><dd>{{ money(document.total) }}</dd></div><div><dt>پرداخت‌شده</dt><dd>{{ money(document.paid_amount) }}</dd></div><div class="balance"><dt>مانده</dt><dd>{{ money(document.remaining_amount) }} <small>تومان</small></dd></div></dl>
    </section>
    <footer class="invoice-footer" data-pdf-block><div class="qr-area"><img v-if="qr" :src="qr" alt="کد QR مشاهده و دانلود فاکتور" width="112" height="112"/><div><strong>نسخهٔ دیجیتال، همراه شما</strong><p>با اسکن، سند را در گوشی مشاهده و PDF را دریافت کنید.</p><small v-if="document.share_token">لینک تا {{ expiryDays }} روز معتبر است؛ با تغییر فاکتور، QR تازه لازم است. آن را فقط با طرف معامله به اشتراک بگذارید.</small><small v-else>لینک اشتراک برای این سند موجود نیست.</small></div></div><span class="footer-label">{{ brand.shortName }} / {{ document.kind === 'purchase' ? 'خرید' : 'فروش' }}</span></footer>
  </article>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import QRCode from 'qrcode'
import { invoiceURL } from '@/services/invoiceDocuments'
import { brand } from '@/config/brand'
const props = defineProps({ document: { type: Object, required: true } })
const qr = ref('')
const emit = defineEmits(['qr-ready'])
let qrRequest = 0
watch(() => props.document.share_token, async () => { const current = ++qrRequest; qr.value = ''; emit('qr-ready', false); const url = invoiceURL(props.document); try { const image = url ? await QRCode.toDataURL(url, { width: 224, margin: 4, errorCorrectionLevel: 'M', color: { dark: '#172f34', light: '#ffffff' } }) : ''; if (current === qrRequest) { qr.value = image; emit('qr-ready', true) } } catch { if (current === qrRequest) emit('qr-ready', false) } }, { immediate: true })
const title = computed(() => props.document.billing_status === 'draft' ? 'پیش‌نویس سفارش' : props.document.billing_status === 'unissued' ? 'سفارش — فاکتور صادر نشده' : `فاکتور ${props.document.kind === 'purchase' ? 'خرید' : 'فروش'}`)
const statusText = computed(() => ({ draft: 'پیش‌نویس', unissued: 'صادر نشده', unpaid: 'پرداخت نشده', partially_paid: 'پرداخت جزئی', paid: 'تسویه‌شده', cancelled: 'لغوشده' })[props.document.billing_status] || props.document.status)
const notice = computed(() => props.document.billing_status === 'cancelled' ? 'این سند لغو شده و قابل استناد برای پرداخت نیست.' : 'این سند فاکتور قطعی نیست؛ وضعیت صدور و تأیید سفارش را بررسی کنید.')
const expiryDays = computed(() => Math.round(Number(props.document.link_expires_in || 2592000) / 86400))
const number = value => new Intl.NumberFormat('fa-IR', { maximumFractionDigits: 3 }).format(Number(value || 0))
const money = value => new Intl.NumberFormat('fa-IR', { maximumFractionDigits: 2 }).format(Number(value || 0))
const date = value => value ? new Date(`${String(value).slice(0, 10)}T12:00:00`).toLocaleDateString('fa-IR') : '—'
</script>
<style>
