or:var(--muted)}.item-index{font-size:10px;color:#52646a;margin-left:7px}.line-total{font-weight:700}.invoice-bottom{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-top:30px}.invoice-notes p{white-space:pre-wrap;overflow-wrap:anywhere;margin-top:8px}.invoice-notes .subtle{color:var(--muted);font-size:10px;margin-top:20px}.invoice-totals>div{padding:6px 0}.invoice-totals .grand-total{border-top:1px solid var(--line);margin-top:8px;padding:15px 12px;background:#eff5f3;align-items:center}.grand-total dd{font-size:24px;color:#205950}.grand-total dt{font-weight:700;color:var(--ink)}.grand-total small{display:block;font-weight:400;font-size:10px}.invoice-totals .balance{border-top:1px solid var(--line);margin-top:6px;padding-top:10px;font-weight:700}.invoice-footer{margin-top:38px;padding-top:20px;border-top:1px solid var(--line);display:flex;align-items:flex-end;justify-content:space-between;gap:20px}.qr-area{display:flex;align-items:center;gap:16px;max-width:480px}.qr-area img{flex:none;width:112px;height:112px}.qr-area strong{font-size:12px}.qr-area p,.qr-area small,.footer-label{font-size:10px;color:var(--muted)}.footer-label{white-space:nowrap}.invoice-items tr,.invoice-bottom,.invoice-footer{break-inside:avoid;page-break-inside:avoid}.invoice-items thead{display:table-header-group}
@media(max-width:600px){.invoice-paper{padding:24px 20px;font-size:13px}.invoice-header{gap:18px;flex-direction:column;padding-bottom:22px}.invoice-heading{text-align:right;display:flex;align-items:center;gap:12px;flex-wrap:wrap}.invoice-heading h1{font-size:23px}.invoice-heading .invoice-eyebrow{display:none}.invoice-details{grid-template-columns:1fr;gap:20px;padding:22px 0}.invoice-details dl{border-top:1px solid var(--line);padding-top:15px}.invoice-items thead{display:none}.invoice-items,.invoice-items tbody,.invoice-items tr{display:block;width:100%}.invoice-items tr{padding:15px 0;border-bottom:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:8px 16px}.invoice-items td{border:0;padding:0;display:block}.invoice-items td:first-child{grid-column:1/-1;margin-bottom:6px}.invoice-items td:not(:first-child)::before{content:attr(data-label);display:block;font-size:10px;color:var(--muted)}.invoice-items td small{display:inline}.invoice-items td:first-child small{display:block}.invoice-bottom{grid-template-columns:1fr;gap:22px;margin-top:24px}.invoice-notes{order:2}.invoice-footer{align-items:flex-start;flex-direction:column}.qr-area{gap:10px}.qr-area img{width:96px;height:96px}}
.invoice-export{width:794px!important;max-width:none!important;padding:0!important}.invoice-export .invoice-header{flex-direction:row}.invoice-export .invoice-heading{text-align:left;display:block}.invoice-export .invoice-heading .invoice-eyebrow{display:inline}.invoice-export .invoice-details,.invoice-export .invoice-bottom{grid-template-columns:1fr 1fr}.invoice-export .invoice-details dl{border:0;padding:0}.invoice-export .invoice-items{display:table}.invoice-export .invoice-items thead{display:table-header-group}.invoice-export .invoice-items tbody{display:table-row-group}.invoice-export .invoice-items tr{display:table-row}.invoice-export .invoice-items td{display:table-cell;padding:17px 8px;border-bottom:1px solid #d9e2e3}.invoice-export .invoice-items td:not(:first-child)::before{display:none}.invoice-export .invoice-items td small{display:block}.invoice-export .invoice-notes{order:0}.invoice-export .invoice-footer{flex-direction:row;align-items:flex-end}
.brand-mark svg{display:block;flex:none}
.invoice-export .brand-mark{display:block;padding:8px;line-height:0}
@page{size:A4;margin:12mm}
@media print{body.invoice-printing > :not(.invoice-print-host){display:none!important}body.invoice-printing .invoice-print-host{display:block!important;position:static!important;width:auto!important}.invoice-paper{max-width:none;padding:0;color:#1c3035;background:white}.invoice-export{width:100%!important}.invoice-print-host .invoice-paper{font-size:11px}.invoice-print-host .invoice-heading h1{font-size:23px}.invoice-print-host .invoice-items td{padding:12px 6px}.invoice-print-host .invoice-brand p{color:#52646a}}
</style>
